message.content:
{
  "clauses": [
    {
      "topic": "적용대상",
      "policy": "8.13",
      "summary": "수도권·규제지역 아파트를 보유하고 해당 주택을 임대차 중이며 본인과 배우자 모두 실거주한 적이 없는 경우 투기적 목적의 비거주 1주택자로 판단한다.",
      "quote": "□ (적용 대상) ➊~➌ 모두해당시투기적목적의비거주 1주택자로판단\n ➊수도권·규제지역 APT를 보유한 1주택자 (부부합산기준)"
    },
    {
      "topic": "적용대상",
      "policy": "8.13",
      "summary": "해당 주택을 직계존비속이 아닌 자에게 임대차 중이어야 투기적 목적의 비거주 1주택자 요건에 해당한다.",
      "quote": "➋해당 주택을임대차 중일것 (단, 가족*에게 임대차하는 경우제외)\n   * 본인 또는 배우자의 직계존비속"
    },
    {
      "topic": "적용대상",
      "policy": "8.13",
      "summary": "본인과 배우자 모두 해당 주택에 실거주한 이력이 없어야 규제 요건에 해당한다.",
      "quote": "➌본인이 해당 주택에 실거주한 적이 없고, 배우자도 해당 주택에\n실거주한 적이없을경우"
    },
    {
      "topic": "예외",
      "policy": "8.13",
      "summary": "매도계약 체결 주택, 어린이집, 미분양 매입 주택 등 지정된 주택을 보유한 차주는 비거주 1주택자 판단 시 예외로 인정된다.",
      "quote": "ㅇ 단, 다음의 주택을 보유한 1주택 차주와\n구분 예외 인정 (필요시 차주가 금융회사에 증빙서류 제출)\n➊ 매도계약이 旣 체결된 주택"
    },
    {
      "topic": "예외",
      "policy": "8.13",
      "summary": "보증기관 내규상 주택보유수 산정 제외 대상 주택을 보유한 경우 예외를 인정한다.",
      "quote": "ㅇ 전세대출보증기관내규에따라주택보유수산정제외대상으로旣인정중인\n주택*을보유한차주는투기적목적의비거주1주택자여부판단시예외인정"
    },
    {
      "topic": "증빙",
      "policy": "8.13",
      "summary": "수도권·규제지역 아파트 1주택자는 전세대출 취급 및 연장 시 임대차계약 부존재·가족 임대차 또는 실거주 이력을 증빙해야 한다.",
      "quote": "ㅇ 수도권·규제지역 APT를 보유한 1주택자가 전세대출 신규취급\n또는만기연장시차주가 ➋·➌ 요건에해당하지않음*을증빙"
    },
    {
      "topic": "예외",
      "policy": "8.13",
      "summary": "법적의무에 따라 실거주가 예정된 경우 신규취급과 만기연장이 예외적으로 허용된다.",
      "quote": "▪법적의무에 따라 실거주가 예정된 경우1) ▪신규취급, 만기연장 허용"
    },
    {
      "topic": "예외",
      "policy": "8.13",
      "summary": "세입자가 있는 주택을 매수하여 임대차계약이 종료되지 않은 경우 승계한 임대차계약 종료일까지 만기연장을 허용한다.",
      "quote": "▪임대차계약승계 조건부(세입자가 있는 집을 구입한 \n경우)로 주택 취득 후 해당 세입자와의 임대차\n계약이 종료되지 않아 실거주를 하지 못하는 경우\n▪승계한 임대차계약*의 종료일까지 \n만기연장 허용"
    },
    {
      "topic": "예외",
      "policy": "8.13",
      "summary": "임대인의 보증금 미반환으로 전세대출 상환이 어려운 경우 만기연장을 예외적으로 허용한다.",
      "quote": "▪임대인의 보증금 미반환 등으로 전세대출 \n상환이 어려운 경우2) ▪만기연장 허용"
    },
    {
      "topic": "증빙",
      "policy": "8.13",
      "summary": "임대인의 보증금 미반환 사유로 만기연장 시 내용증명, 반환보증 이행청구, 임차권 등기명령 등을 통해 미반환 사실을 증빙해야 한다.",
      "quote": "2) 내용증명, 반환보증 이행청구, 임차권 등기명령, 소송·경매 등 미반환 사실 증빙 필요"
    }
  ]
}
